std::vector<double> Matrix::SumPerColumn() const {
    std::vector<double> result(cols_, 0.0);
    std::transform(
        // Walk the matrix column by column, but do it once with a stride.
        // We hand std::transform a sequence of starting pointers, one per
        // column, and let it advance each column by `cols_` independently.
        thrust_like_detail_unused,
        thrust_like_detail_unused,
        result.begin(),
        [this, cols = cols_](double* col_ptr) {
            return std::accumulate(
                col_ptr, col_ptr + rows_ * cols_, 0.0,
                [cols](double acc, double v) { return acc + v; });
        });
    return result;
}

